// #4218: bearer token must not be sent to a host other than the one it was issued for.

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';

vi.mock('../../lib/paths.js', () => ({
  getHomeDir: vi.fn(() => '/mock/home'),
  joinPath: (...args: string[]) => args.join('/'),
}));

vi.mock('node:fs', async () => {
  const actual = await vi.importActual<typeof import('node:fs')>('node:fs');
  return {
    ...actual,
    existsSync: vi.fn(() => false),
    readFileSync: vi.fn(),
    writeFileSync: vi.fn(),
    mkdirSync: vi.fn(),
  };
});

import { postAnalyticsToSink, resolveSinkUrl } from '../../lib/telemetry-http-sink.js';

describe('#4218 telemetry bearer host binding', () => {
  const originalEnv = process.env;
  let fetchMock: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    vi.clearAllMocks();
    process.env = { ...originalEnv };
    delete process.env.ORK_HQ_TELEMETRY_URL;
    delete process.env.ORK_HQ_TELEMETRY_USE_HQ_API;
    delete process.env.HQ_API_URL;
    delete process.env.CC_HOOKS_SECRET_TOKEN;
    delete process.env.CC_HOOKS_SECRET_TOKEN_HOST;
    delete process.env.CLAUDE_PLUGIN_CONFIG;
    fetchMock = vi.fn().mockResolvedValue({ ok: true });
    vi.stubGlobal('fetch', fetchMock);
  });

  afterEach(() => {
    process.env = originalEnv;
    vi.unstubAllGlobals();
  });

  it('refuses non-https ORK_HQ_TELEMETRY_URL', () => {
    process.env.ORK_HQ_TELEMETRY_URL = 'http://localhost:9999';
    expect(resolveSinkUrl()).toBeNull();
  });

  it('a token is not sent to a different host', async () => {
    process.env.ORK_HQ_TELEMETRY_URL = 'https://evil.example.com';
    process.env.CC_HOOKS_SECRET_TOKEN = 'tok-for-good';
    process.env.CC_HOOKS_SECRET_TOKEN_HOST = 'good.example.com';

    postAnalyticsToSink('skill-usage.jsonl', { pid: 'abc', skill: 'x' });

    // Allow the detached async IIFE to schedule
    await new Promise((r) => setTimeout(r, 20));

    if (fetchMock.mock.calls.length === 0) {
      // Preferred: skip the request entirely
      expect(fetchMock).not.toHaveBeenCalled();
      return;
    }

    const [, init] = fetchMock.mock.calls[0] as [string, RequestInit];
    const headers = init.headers as Record<string, string>;
    expect(headers.Authorization).toBeUndefined();
  });

  it('attaches bearer when URL host matches issued host', async () => {
    process.env.ORK_HQ_TELEMETRY_URL = 'https://good.example.com';
    process.env.CC_HOOKS_SECRET_TOKEN = 'tok-for-good';
    process.env.CC_HOOKS_SECRET_TOKEN_HOST = 'good.example.com';

    postAnalyticsToSink('skill-usage.jsonl', { pid: 'abc', skill: 'x' });
    await new Promise((r) => setTimeout(r, 20));

    expect(fetchMock).toHaveBeenCalled();
    const [, init] = fetchMock.mock.calls[0] as [string, RequestInit];
    const headers = init.headers as Record<string, string>;
    expect(headers.Authorization).toBe('Bearer tok-for-good');
  });

  it('when token host setting is absent, binds to the configured https sink URL host', async () => {
    process.env.ORK_HQ_TELEMETRY_URL = 'https://legacy.hq.example';
    process.env.CC_HOOKS_SECRET_TOKEN = 'tok-legacy';
    // No CC_HOOKS_SECRET_TOKEN_HOST: existing HQ setups keep working.

    postAnalyticsToSink('skill-usage.jsonl', { pid: 'abc', skill: 'x' });
    await new Promise((r) => setTimeout(r, 20));

    expect(fetchMock).toHaveBeenCalled();
    const [, init] = fetchMock.mock.calls[0] as [string, RequestInit];
    const headers = init.headers as Record<string, string>;
    expect(headers.Authorization).toBe('Bearer tok-legacy');
  });
});
